import {agentLabel,libraryIcon} from '/agent-appearance.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class AgentToolMenu {
  constructor(button,scope,{api,onSaved,onClose,onManage}){
    this.onManage=onManage;this.button=button;this.scope=scope;this.onClose=onClose;this.api=api;this.onSaved=onSaved;
    this.element=document.createElement('section');this.element.className='agent-tool-menu';this.element.setAttribute('popover','manual');this.element.setAttribute('aria-label',scope.role+' toolbox');
    const optional=scope.tools.filter(t=>!t.locked),core=scope.tools.filter(t=>t.locked);
    this.approvals=structuredClone(scope.approvals||{shared:{default:'ask',tools:{}},native:{default:'ask',tools:{}}});
    const permission=(group,name,label)=>{const mode=this.approvals[group].tools[name]||'default';return `<label class="tool-approval-setting"><span>Approval</span><select data-approval-group="${group}" data-approval-tool="${esc(name)}" aria-label="Approval for ${esc(label||name)}"><option value="default" ${mode==='default'?'selected':''}>Use toolbox setting</option><option value="ask" ${mode==='ask'?'selected':''}>Always ask</option><option value="allow" ${mode==='allow'?'selected':''}>Always allow</option></select></label>`;};
    const bulk=(group,label)=>`<div class="tool-approval-bulk"><strong>${label}</strong><div role="group" aria-label="${label} approval defaults"><button type="button" data-approval-all="ask" data-approval-section="${group}" aria-pressed="${this.approvals[group].default==='ask'}">Always ask</button><button type="button" data-approval-all="allow" data-approval-section="${group}" aria-pressed="${this.approvals[group].default==='allow'}">Allow all tools</button></div></div>`;
    const row=t=>`<div class="scoped-tool"><label class="scoped-tool-access"><input type="checkbox" name="allowed" value="${esc(t.name)}" ${t.allowed?'checked':''} ${t.locked?'disabled':''}><span><strong>${esc(t.source?.toolName||t.name)}</strong><small>${esc(t.source?.type==='mcp'?t.description.split('\n').slice(1).join('\n'):t.description)}</small></span></label>${t.name==='invoke_tool'?'<small class="approval-wrapper-note">Uses the requested tool’s approval rule.</small>':permission('shared',t.name,t.source?.toolName||t.name)}</div>`;
    const groups=new Map();for(const tool of optional.filter(t=>t.source?.type==='mcp')){if(!groups.has(tool.source.id))groups.set(tool.source.id,{...tool.source,tools:[]});groups.get(tool.source.id).tools.push(tool);}
    const optionalHTML=`<div class="scoped-local-tools">${optional.filter(t=>t.source?.type!=='mcp').map(row).join('')}</div>`+[...groups.values()].map(group=>`<details class="scoped-mcp-tools" open><summary><strong>${esc(group.name)}</strong> · ${group.tools.length} tools · ${group.scope==='global'?'Global':'Project'}</summary>${group.tools.map(row).join('')}${onManage?`<button type="button" class="mcp-menu-manage" data-manage-mcp="${group.id}">${libraryIcon('settings-2',13)} Availability & assignment</button>`:''}</details>`).join('');
    this.element.innerHTML=`<form id="pack-scope-form"><header><div><strong>${agentLabel(scope.taskId,scope.role)}’s toolbox</strong><small>Access enforced by HeloScrum</small></div><button type="button" data-close aria-label="Close agent toolbox">×</button></header><div class="tool-menu-scroll"><label class="scope-field">Available tools<select name="mode" aria-label="Tool access mode"><option value="all" ${scope.mode==='all'?'selected':''}>All current and future tools</option><option value="selected" ${scope.mode==='selected'?'selected':''}>Only selected tools</option></select></label>${bulk('shared','Shared tool approvals')}<p class="scope-note approval-help">Applied when the provider asks for permission. Individual tool settings override the toolbox setting.</p>${scope.approvalSupport?`<p class="scope-note approval-help">${esc(scope.approvalSupport)}</p>`:''}<div class="scoped-tool-list">${optionalHTML||'<p>No optional tools registered yet.</p>'}</div><details class="core-tool-list"><summary>Always available · ${core.length} coordination tools and contacts</summary>${core.map(row).join('')}</details><section class="native-tool-approvals">${bulk('native','Provider-native approvals')}<p class="scope-note approval-help">${(scope.nativeTools||[]).length===1?'Workspace shell commands':'Shell, files, web and other recognized provider requests'}. Existing CLI permissions and sandbox limits still apply. Always ask means HeloScrum will not auto-approve; actions the CLI already permits may run without a prompt.</p>${(scope.nativeTools||[]).map(t=>`<div class="scoped-tool native-approval-tool"><span><strong>${esc(t.label)}</strong><small>${esc(t.description)}</small></span>${permission('native',t.name,t.label)}</div>`).join('')}</section>${scope.roleType!=='recovery'?`<label class="scope-field recovery-contact"><span>Recovery contact <small>optional</small></span><select name="supportAgentId" aria-label="Recovery contact"><option value="">No coach assigned</option>${scope.coaches.map(c=>`<option value="${esc(c.id)}" ${scope.supportAgentId===c.id?'selected':''}>${esc(c.role)}</option>`).join('')}</select></label><p class="scope-note">Help with blockers, conflicting instructions and the next step.${scope.coaches.length?'':' Add an agent from the Therapist template, then assign it here.'}</p>`:'<p class="scope-note">Recovery coaches reply directly to teammates. Support requests cannot chain between coaches.</p>'}${onManage?`<button type="button" class="tool-menu-manage" data-manage-mcp="">${libraryIcon('settings-2',14)} Manage tools & MCPs</button>`:''}<p class="scope-note">Rules are saved for this agent and survive session changes. Disabled shared tools stay disabled. Setup dialogs, questions and unrecognized requests still need your response.</p></div><footer><p class="scope-error" role="alert"></p><button type="submit" class="primary">Save toolbox</button></footer></form>`;
    document.body.append(this.element);this.element.showPopover();button.setAttribute('aria-expanded','true');
    this.mode=this.element.querySelector('[name=mode]');this.mode.onchange=()=>this.syncMode();this.element.addEventListener('change',()=>this.syncApprovals());this.syncMode();this.syncApprovals();
    this.element.querySelector('[data-close]').onclick=()=>this.close();
    this.element.addEventListener('click',event=>{const approval=event.target.closest('[data-approval-all]');if(approval){const group=approval.dataset.approvalSection;this.approvals[group]={default:approval.dataset.approvalAll,tools:{}};for(const select of this.element.querySelectorAll(`[data-approval-group="${group}"]`))select.value='default';this.syncApprovals();return;}const target=event.target.closest('[data-manage-mcp]');if(target){this.close();this.onManage?.(target.dataset.manageMcp||undefined);}});
    this.element.querySelector('form').onsubmit=event=>{event.preventDefault();this.save().catch(error=>{this.element.querySelector('.scope-error').textContent=error.message;});};
    this.outside=event=>{if(!this.element.contains(event.target)&&!button.contains(event.target))this.close(false);};
    this.key=event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();this.close();}};
    this.resize=()=>this.place();document.addEventListener('pointerdown',this.outside);document.addEventListener('keydown',this.key,true);window.addEventListener('resize',this.resize);window.addEventListener('scroll',this.resize,true);
    this.place();this.mode.focus();
  }
  syncMode(){const all=this.mode.value==='all';for(const input of this.element.querySelectorAll('[name=allowed]')){const core=this.scope.tools.find(t=>t.name===input.value)?.locked;input.disabled=all||core;if(all||core)input.checked=true;}this.element.classList.toggle('scope-all',all);this.syncApprovals();}
  syncApprovals(){for(const button of this.element.querySelectorAll('[data-approval-all]'))button.setAttribute('aria-pressed',String(button.dataset.approvalAll===this.approvals[button.dataset.approvalSection].default));for(const select of this.element.querySelectorAll('[data-approval-tool]')){select.options[0].textContent='Use toolbox setting · '+(this.approvals[select.dataset.approvalGroup].default==='allow'?'Allow':'Ask');const access=select.closest('.scoped-tool').querySelector('[name=allowed]');select.disabled=!!access&&!access.checked;}}
  place(){if(!this.element.isConnected)return;const rect=this.button.getBoundingClientRect(),width=Math.min(460,innerWidth-20),height=Math.min(540,innerHeight-24);this.element.style.width=width+'px';this.element.style.maxHeight=height+'px';this.element.style.left=Math.max(10,Math.min(rect.right-width,innerWidth-width-10))+'px';this.element.style.top=Math.max(12,Math.min(rect.bottom+6,innerHeight-height-12))+'px';}
  async save(){
    if(this.saving)return;this.saving=true;const button=this.element.querySelector('[type=submit]');button.disabled=true;
    try{for(const group of ['shared','native'])this.approvals[group].tools=Object.fromEntries([...this.element.querySelectorAll(`[data-approval-group="${group}"]`)].filter(e=>e.value!=='default').map(e=>[e.dataset.approvalTool,e.value]));const result=await this.api('agent-tools',{taskId:this.scope.taskId,expectedRevision:this.scope.revision,approvals:this.approvals,mode:this.mode.value,allowed:[...this.element.querySelectorAll('[name=allowed]:checked')].map(e=>e.value).filter(name=>!this.scope.tools.find(t=>t.name===name)?.locked),supportAgentId:this.element.querySelector('[name=supportAgentId]')?.value||null});await this.onSaved(result);this.close();}
    finally{this.saving=false;button.disabled=false;}
  }
  close(focus=true){if(this.closed)return;this.closed=true;this.element.hidePopover();this.element.remove();this.button.setAttribute('aria-expanded','false');document.removeEventListener('pointerdown',this.outside);document.removeEventListener('keydown',this.key,true);window.removeEventListener('resize',this.resize);window.removeEventListener('scroll',this.resize,true);if(focus&&this.button.isConnected)this.button.focus();this.onClose?.();}
}
